QuantResearchPage::~QuantResearchPage(){cancelRun();guard([this]{persist();});}
void QuantResearchPage::guard(std::function<void()>fn){try{fn();}catch(const std::exception&e){if(status)status->setText(QString::fromUtf8(e.what()));}}
void QuantResearchPage::fill(const QJsonObject&c){filling=true;familyPicker->setCurrentIndex(std::max(0,int(families().indexOf(c.value("family").toString()))));for(auto k:configKeys())fields[k]->setText(QString::number(c.value(k).toDouble(),'g',16));parameters->setPlainText(QString::fromUtf8(QJsonDocument(c.value("parameters").toArray()).toJson(QJsonDocument::Indented)));filling=false;}
QJsonObject QuantResearchPage::config()const{QJsonObject c{{"family",families()[familyPicker->currentIndex()]}};for(auto k:configKeys()){bool ok=false;double n=fields[k]->text().toDouble(&ok);need(ok&&std::isfinite(n),"无效参数: "+k);c[k]=n;}QJsonParseError e;auto doc=QJsonDocument::fromJson(parameters->toPlainText().toUtf8(),&e);need(e.error==QJsonParseError::NoError&&doc.isArray(),"参数组合需要完整JSON数组");c["parameters"]=doc.array();validateConfig(c);return c;}
void QuantResearchPage::refresh(){setProperty("quantSnapshotBusy",true);status->setText("正在后台核验量化资料与材料版本；已有选择和草稿保留。");if(snapshotReader)snapshotReader->request();}
void QuantResearchPage::showRecord(QString id){showRecordObject(store->get(id));}
void QuantResearchPage::showRecordObject(const QJsonObject& r){auto id=r.value("id").toString();selectedId=id;summary->clear();summary->addItem("完整身份: "+id);summary->addItem("类型 / 状态: "+r.value("kind").toString()+" / "+r.value("status").toString());if(r.value("kind")=="run"){summary->addItem("冻结数据摘要: "+r.value("datasetId").toString());summary->addItem("材料版本数: "+QString::number(r.value("materials").toArray().size()));for(auto v:r.value("result").toObject().value("parameters").toArray()){auto p=v.toObject(),m=p.value("metrics").toObject();summary->addItem(QString("%1 · %2 · OOS均值%3% · 中位%4% · 最差%5% · 完成成交%6").arg(p.value("parameterId").toString(),p.value("admission").toString()).arg(m.value("meanOosReturn").toDouble()*100,0,'f',3).arg(m.value("medianOosReturn").toDouble()*100,0,'f',3).arg(m.value("worstOosReturn").toDouble()*100,0,'f',3).arg(m.value("tradeCount").toInt()));}if(!r.value("error").toString().isEmpty())summary->addItem(r.value("error").toString());summary->addItem("探索性统计；完整记录含窗口、选参、成交、权益和未平仓证据");}else{auto o=r.value("original").toObject();summary->addItem("来源: "+o.value("source").toString());summary->addItem("实际文件SHA256: "+r.value("id").toString());summary->addItem("核验状态: "+r.value("verification").toString());if(r.value("kind")=="archive")summary->addItem("旧模型: "+o.value("modelId").toString()+"；未重跑，附件未独立核验");}views->setCurrentIndex(1);}
