void QuantResearchPage::showText(QString t){readerText=t;readerOffset=0;renderReader();views->setCurrentIndex(2);}
void QuantResearchPage::renderReader(){int start=readerOffset,end=std::min(start+24000,int(readerText.size()));if(start>0&&readerText[start].isLowSurrogate())start--;if(end>0&&end<readerText.size()&&readerText[end-1].isHighSurrogate())end--;reader->setPlainText(readerText.mid(start,end-start));status->setText(QString("完整记录分段读取 %1–%2 / %3 字符；导出保留全量").arg(start).arg(end).arg(readerText.size()));}
void QuantResearchPage::previewImport(const QByteArray&b){need(snapshotReady,"量化只读快照尚未就绪，请等待或重读");need(!cancellation,"本页运行结束后再导入");pending=importText(b);pendingBaseline=store->read();showText(QString::fromUtf8(QJsonDocument(pending.value("original").toObject()).toJson(QJsonDocument::Indented)));status->setText(pending.value("original").toObject().contains("parquetSelectionEvidence")?"所选Parquet清单、附件、证券和范围已核验；仅预览，确认后加入Quant输入，不启动训练。":"仅预览，未写入；检查来源/日期/模型后确认。旧结果附件仍未核验。");persist();}
void QuantResearchPage::confirmImport(){need(snapshotReady,"量化只读快照尚未就绪，请等待或重读");need(!pending.isEmpty(),"没有待确认预览");store->merge(pending,pendingBaseline);pending={};pendingBaseline={};views->setCurrentIndex(1);persist();refresh();status->setText("导入完成，原始文件完整保留");}
void QuantResearchPage::cancelImport(){pending={};pendingBaseline={};views->setCurrentWidget(form);status->setText("预览已取消");guard([this]{persist();});}
bool QuantResearchPage::back(){cancelRun();if(models)models->leave();if(views->currentWidget()==parquet){parquet->stop();views->setCurrentWidget(form);return true;}if(views->currentIndex()==3){views->setCurrentWidget(form);return true;}if(views->currentIndex()==2){if(!pending.isEmpty())cancelImport();else views->setCurrentIndex(1);return true;}if(views->currentIndex()==1){views->setCurrentWidget(form);return true;}guard([this]{persist();});return false;}
