void QuantResearchPage::applyState(QJsonObject o){need(o.value("schema")=="quant-native-view/v1","草稿格式无效");int f=o.value("familyIndex").toInt(-1);need(f>=0&&f<families().size()&&o.value("fields").isObject()&&o.value("parametersText").isString()&&o.value("materials").isArray(),"草稿缺少完整字段");filling=true;familyPicker->setCurrentIndex(f);for(auto k:configKeys()){need(o.value("fields").toObject().value(k).isString(),"草稿字段缺失");fields[k]->setText(o.value("fields").toObject().value(k).toString());}parameters->setPlainText(o.value("parametersText").toString());materials=o.value("materials").toArray();selectedId=o.value("selectedId").toString();auto wanted=o.value("datasetId").toString();int i=datasetPicker->findData(wanted);if(i<0&&!wanted.isEmpty()){datasetPicker->addItem("原选数据包暂不在快照："+wanted,wanted);i=datasetPicker->count()-1;}if(i>=0)datasetPicker->setCurrentIndex(i);pending=o.value("pending").toObject();pendingBaseline=o.value("pendingBaseline").toObject();readerText=o.value("readerText").toString();readerOffset=o.value("readerOffset").toInt();need(readerOffset>=0&&readerOffset<=readerText.size(),"正文位置无效");int mode=o.value("mode").toInt();parquetState=o.value("parquetView").toObject();if(parquet)parquet->restoreState(parquetState);need(mode>=0&&mode<=4,"页面模式无效");if(mode==1&&!selectedId.isEmpty()){bool found=false;for(auto v:workspaceSnapshot.value("records").toArray())if(v.toObject().value("id")==selectedId){showRecordObject(v.toObject());found=true;break;}if(!found)views->setCurrentIndex(1);}else{if(mode==4)ensureParquet();views->setCurrentIndex(mode);}if(mode==2)renderReader();filling=false;}
void QuantResearchPage::restoreState(const QJsonObject&o){auto request=std::make_shared<const QJsonObject>(QJsonObject{{"serial",double(++restoreSerial)},{"state",o}});std::atomic_store(restoreRequest.get(),request);refresh();}
void QuantResearchPage::persist(){if(!snapshotReady)return;auto state=saveState();if(state==cleanUiState)return;need(viewWritable,"草稿文件不可读，保留内存草稿，未覆盖");store->saveView(state,viewBaseline);viewBaseline=state;cleanUiState=state;}
void QuantResearchPage::hideEvent(QHideEvent*e){cancelRun();guard([this]{persist();});QWidget::hideEvent(e);}
void QuantResearchPage::setDarkTheme(bool dark){auto wanted=QString(dark?"QWidget{background:#142033;color:#eef4ff;} QLineEdit,QPlainTextEdit,QListWidget,QComboBox{background:#202e42;color:#eef4ff;border:1px solid #52647f;} QPushButton{background:#304563;color:#fff;border:1px solid #607a9e;padding:6px;} QComboBox QAbstractItemView{background:#202e42;color:#fff;}":"QWidget{background:#f5f7fb;color:#172235;} QLineEdit,QPlainTextEdit,QListWidget,QComboBox{background:white;color:#172235;border:1px solid #c0ccdb;} QPushButton{background:#e3ebf6;color:#172235;border:1px solid #a7bad2;padding:6px;}");if(styleSheet()!=wanted)setStyleSheet(wanted);}
bool QuantResearchPage::cancelRun(){if(!cancellation)return false;auto phase=RunActive;return cancellation->compare_exchange_strong(phase,RunCancelRequested)||phase==RunCancelRequested;}

void QuantResearchPage::ensureModels(){if(models)return;models=new QuantModelWidget(store->filePath()+".model-jobs");auto shell=views->widget(3);views->removeWidget(shell);shell->deleteLater();views->insertWidget(3,models);}
void QuantResearchPage::ensureParquet(){if(parquet)return;parquet=new QuantParquetWidget(QFileInfo(store->filePath()).absolutePath(),[this](QByteArray bytes){guard([this,bytes]{previewImport(bytes);});});parquet->setChartOpener(parquetChartOpener);parquet->restoreState(parquetState);auto shell=views->widget(4);views->removeWidget(shell);shell->deleteLater();views->insertWidget(4,parquet);}
